use core::fmt::Write as _;
use core::mem;

use std::collections::{BTreeSet, HashMap, HashSet};

use anyhow::{Result, bail};
use wit_bindgen_core::wit_parser::{
    Docs, Function, FunctionKind, Handle, InterfaceId, PackageId, Resolve, Type, TypeDefKind,
    TypeId, TypeOwner, WorldId, WorldItem, WorldKey,
};
use wit_bindgen_core::{Files, WorldGenerator, dealias, uwrite, uwriteln};
use wrpc_introspect::{async_paths_ty, rpc_func_name};

fn generated_preamble() -> String {
    format!(
        "// Generated by `wit-bindgen-wrpc-js` {}. DO NOT EDIT!\n",
        env!("CARGO_PKG_VERSION")
    )
}

#[cfg(feature = "clap")]
fn parse_with(s: &str) -> Result<(String, WithOption), String> {
    let (k, v) = s.split_once('=').ok_or_else(|| {
        format!("expected string of form `<key>=<value>[,<key>=<value>...]`; got `{s}`")
    })?;
    let v = match v {
        "generate" => WithOption::Generate,
        other => WithOption::Path(other.to_string()),
    };
    Ok((k.to_string(), v))
}

/// Represents options for remapping interface bindings.
#[derive(Debug, Clone)]
pub enum WithOption {
    /// Remap the interface to an existing JavaScript module, imported by this
    /// specifier from every module, so it must not be relative.
    Path(String),
    /// Generate the interface bindings.
    Generate,
}

/// Options of the JavaScript bindings generator.
#[derive(Debug, Clone, Default)]
#[cfg_attr(feature = "clap", derive(clap::Parser))]
pub struct Opts {
    /// Remapping of imported interface names to JavaScript module
    /// specifiers, which are imported as given, so they must not be relative.
    ///
    /// Argument must be of the form `k=v` and this option can be passed
    /// multiple times or one option can be comma separated, for example
    /// `k1=v1,k2=v2`.
    #[cfg_attr(feature = "clap", arg(long, value_parser = parse_with, value_delimiter = ','))]
    pub with: Vec<(String, WithOption)>,

    /// Indicates that all imported interfaces not specified in `with` should
    /// be generated.
    #[cfg_attr(feature = "clap", arg(long))]
    pub generate_all: bool,

    /// The optional module specifier of the `@bytecodealliance/wrpc` package
    /// to import, as given, so it must not be relative.
    ///
    /// This defaults to `@bytecodealliance/wrpc`.
    #[cfg_attr(feature = "clap", arg(long, value_name = "SPECIFIER"))]
    pub wrpc_path: Option<String>,
}

impl Opts {
    /// Builds the bindings generator.
    #[must_use]
    pub fn build(self) -> Box<dyn WorldGenerator> {
        Box::new(JsWrpc {
            opts: self,
            ..JsWrpc::default()
        })
    }
}

#[derive(Clone, PartialEq)]
enum ModulePath {
    /// A generated module, by its path relative to the output directory,
    /// without the extension.
    Local(String),
    /// A module specifier given by `with`.
    External(String),
}

#[derive(Default)]
struct Module {
    js: String,
    dts: String,
    /// The `@bytecodealliance/wrpc` exports used by `js`.
    runtime: BTreeSet<&'static str>,
    /// Whether `dts` uses `@bytecodealliance/wrpc` types.
    wrpc_types: bool,
    /// The specifiers of the modules imported, by alias index, and whether
    /// `js` uses them.
    deps: Vec<(String, bool)>,
}

impl Module {
    /// The source of the module and its declarations.
    fn render(self, wrpc: &str) -> (String, String) {
        let Self {
            js: src,
            dts: decls,
            runtime,
            wrpc_types,
            deps,
        } = self;
        let mut js = generated_preamble();
        if !runtime.is_empty() {
            let names: Vec<_> = runtime.iter().map(|n| format!("{n} as ${n}")).collect();
            uwriteln!(js, "import {{ {} }} from {wrpc:?};", names.join(", "));
        }
        let mut dts = generated_preamble();
        if wrpc_types {
            uwriteln!(dts, "import type * as $wrpc from {wrpc:?};");
        }
        for (i, (spec, used)) in deps.iter().enumerate() {
            if *used {
                uwriteln!(js, "import * as ${i} from {spec:?};");
            }
            uwriteln!(dts, "import type * as ${i} from {spec:?};");
        }
        js.push('\n');
        js.push_str(&src);
        dts.push('\n');
        dts.push_str(&decls);
        (js, dts)
    }
}

#[derive(Default)]
struct JsWrpc {
    opts: Opts,
    with: HashMap<String, WithOption>,
    used_with: HashSet<String>,
    world: String,
    interfaces: HashMap<InterfaceId, ModulePath>,
    modules: Vec<(String, Module)>,
    world_module: Module,
    /// The instances served by the world's `serve`, with the module serving
    /// each, or `None` for the world's own functions.
    exports: Vec<(String, Option<ModulePath>)>,
}

impl JsWrpc {
    fn module(&self, path: String, m: Module) -> Gen<'_> {
        Gen {
            interfaces: &self.interfaces,
            world: &self.world,
            path,
            m,
        }
    }

    fn name_interface(
        &mut self,
        resolve: &Resolve,
        id: InterfaceId,
        name: &WorldKey,
        is_export: bool,
    ) -> Result<Option<String>> {
        if !is_export {
            let with_name = resolve.name_world_key(name);
            match self.with.get(&with_name) {
                Some(WithOption::Generate) => {
                    self.used_with.insert(with_name);
                }
                Some(WithOption::Path(path)) => {
                    self.interfaces
                        .insert(id, ModulePath::External(path.clone()));
                    self.used_with.insert(with_name);
                    return Ok(None);
                }
                None if self.opts.generate_all => {}
                None => bail!(
                    "no remapping found for {with_name:?} - use `--generate-all` or `--with {with_name}=generate` to generate bindings for this interface"
                ),
            }
        }
        let mut path = Vec::default();
        if is_export {
            path.push("exports".to_string());
        }
        match name {
            WorldKey::Name(name) => {
                if !is_export {
                    path.push("imports".to_string());
                }
                path.push(name.clone());
            }
            WorldKey::Interface(id) => {
                let iface = &resolve.interfaces[*id];
                let pkg = iface.package.expect("interface package missing");
                path.push(resolve.packages[pkg].name.namespace.clone());
                path.push(name_package_module(resolve, pkg));
                path.push(iface.name.clone().expect("interface name missing"));
            }
        }
        let path = path.join("/");
        self.interfaces.insert(id, ModulePath::Local(path.clone()));
        Ok(Some(path))
    }
}

/// The module name of package `id`: its name, followed by its version if
/// several versions of it are in use.
fn name_package_module(resolve: &Resolve, id: PackageId) -> String {
    let pkg = &resolve.packages[id];
    let versions = resolve
        .packages
        .iter()
        .filter(|(.., p)| p.name.namespace == pkg.name.namespace && p.name.name == pkg.name.name)
        .count();
    match &pkg.name.version {
        Some(version) if versions > 1 => format!("{}@{version}", pkg.name.name),
        _ => pkg.name.name.clone(),
    }
}

fn interface_instance(resolve: &Resolve, name: &WorldKey, id: InterfaceId) -> String {
    let iface = &resolve.interfaces[id];
    let name = match name {
        WorldKey::Name(s) => s.clone(),
        WorldKey::Interface(..) => iface.name.clone().expect("interface name missing"),
    };
    match iface.package {
        Some(pkg) => resolve.id_of_name(pkg, &name),
        None => name,
    }
}

/// The specifier of the module at `to` relative to the module at `from`.
fn relative(from: &str, to: &str) -> String {
    let depth = from.split('/').count();
    if depth > 1 {
        format!("{}{to}.js", "../".repeat(depth.saturating_sub(1)))
    } else {
        format!("./{to}.js")
    }
}

fn is_acronym(s: &str) -> bool {
    s.chars()
        .all(|c| c.is_ascii_digit() || c.is_ascii_uppercase())
}

fn capitalize(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) => c.to_uppercase().chain(chars).collect(),
        None => String::default(),
    }
}

/// The camel case form of the WIT name `name`, like the JS-API draft and the
/// `@bytecodealliance/wrpc` runtime name record fields and flags.
fn camel_case(name: &str) -> String {
    let mut parts = name.split('-');
    let mut out = parts.next().unwrap_or_default().to_lowercase();
    for part in parts {
        if is_acronym(part) {
            out.push_str(part);
        } else {
            out.push_str(&capitalize(part));
        }
    }
    out
}

fn upper_camel_case(name: &str) -> String {
    name.split('-')
        .map(|part| {
            if is_acronym(part) {
                part.to_string()
            } else {
                capitalize(part)
            }
        })
        .collect()
}

/// The name of the type `name` in JavaScript.
fn type_name(name: &str) -> String {
    match upper_camel_case(name).as_str() {
        "Handler" => "Handler_".to_string(),
        s => s.to_string(),
    }
}

/// The JavaScript identifier of the WIT name `name`.
fn js_ident(name: &str) -> String {
    let name = camel_case(name);
    match name.as_str() {
        "arguments" | "await" | "break" | "case" | "catch" | "class" | "const" | "continue"
        | "debugger" | "default" | "delete" | "do" | "else" | "enum" | "eval" | "export"
        | "extends" | "false" | "finally" | "for" | "function" | "globalThis" | "if"
        | "implements" | "import" | "in" | "instanceof" | "interface" | "let" | "new" | "null"
        | "package" | "private" | "protected" | "public" | "return" | "static" | "super"
        | "switch" | "then" | "this" | "throw" | "true" | "try" | "typeof" | "var" | "void"
        | "while" | "with" | "yield" => {
            format!("{name}_")
        }
        _ => name,
    }
}

/// The JavaScript identifier of the parameter `name`.
fn param_ident(name: &str) -> String {
    match js_ident(name).as_str() {
        "transport" => "transport_".to_string(),
        s => s.to_string(),
    }
}

/// `ty` with its aliases resolved.
fn peel(resolve: &Resolve, mut ty: Type) -> Type {
    while let Type::Id(id) = ty
        && let TypeDefKind::Type(t) = resolve.types[id].kind
    {
        ty = t;
    }
    ty
}

/// Whether values of `ty` may be promises: a `future`, or an `option` of
/// one, which is `undefined` or its value.
fn may_be_promise(resolve: &Resolve, ty: Type) -> bool {
    let Type::Id(id) = peel(resolve, ty) else {
        return false;
    };
    match resolve.types[id].kind {
        TypeDefKind::Future(..) => true,
        TypeDefKind::Option(ty) => !is_option(resolve, ty) && may_be_promise(resolve, ty),
        _ => false,
    }
}

/// Whether `ty` is an `option`.
fn is_option(resolve: &Resolve, ty: Type) -> bool {
    matches!(peel(resolve, ty), Type::Id(id) if matches!(resolve.types[id].kind, TypeDefKind::Option(..)))
}

/// The resource `func` belongs to, if any.
fn func_resource(func: &Function) -> Option<TypeId> {
    match func.kind {
        FunctionKind::Constructor(id)
        | FunctionKind::Method(id)
        | FunctionKind::Static(id)
        | FunctionKind::AsyncMethod(id)
        | FunctionKind::AsyncStatic(id) => Some(id),
        FunctionKind::Freestanding | FunctionKind::AsyncFreestanding => None,
    }
}

/// The name of `func` in JavaScript, as a key of its resource's object if it
/// belongs to one.
fn func_name(func: &Function) -> String {
    match func.kind {
        FunctionKind::Constructor(..) => "new".to_string(),
        FunctionKind::Freestanding | FunctionKind::AsyncFreestanding => js_ident(&func.name),
        _ => {
            let name = rpc_func_name(func);
            let (.., name) = name.split_once('.').expect("failed to split on `.`");
            match camel_case(name).as_str() {
                "new" => "new_".to_string(),
                s => s.to_string(),
            }
        }
    }
}

fn ts_docs(docs: &Docs, indent: &str) -> String {
    let Some(contents) = &docs.contents else {
        return String::default();
    };
    let mut out = format!("{indent}/**\n");
    for line in contents.trim().lines() {
        let line = line.replace("*/", "*\\/");
        if line.is_empty() {
            uwriteln!(out, "{indent} *");
        } else {
            uwriteln!(out, "{indent} * {line}");
        }
    }
    uwriteln!(out, "{indent} */");
    out
}

struct Gen<'a> {
    interfaces: &'a HashMap<InterfaceId, ModulePath>,
    world: &'a str,
    path: String,
    m: Module,
}

impl Gen<'_> {
    /// The alias of the module at `target`.
    fn dep(&mut self, target: &ModulePath, js: bool) -> String {
        let spec = match target {
            ModulePath::Local(path) => relative(&self.path, path),
            ModulePath::External(spec) => spec.clone(),
        };
        let i = if let Some(i) = self.m.deps.iter().position(|(s, ..)| *s == spec) {
            i
        } else {
            self.m.deps.push((spec, false));
            self.m.deps.len().saturating_sub(1)
        };
        if js {
            self.m.deps[i].1 = true;
        }
        format!("${i}")
    }

    /// A reference to the named type `id`, unless it is anonymous.
    fn type_ref(&mut self, resolve: &Resolve, id: TypeId, js: bool) -> Option<String> {
        let def = &resolve.types[id];
        let name = def.name.as_deref()?;
        let name = type_name(name);
        let path = match def.owner {
            TypeOwner::Interface(id) => {
                let path = self.interfaces.get(&id)?;
                path.clone()
            }
            TypeOwner::World(..) => ModulePath::Local(self.world.to_string()),
            TypeOwner::None => return None,
        };
        if path == ModulePath::Local(self.path.clone()) {
            return Some(name);
        }
        let dep = self.dep(&path, js);
        Some(format!("{dep}.{name}"))
    }

    /// The type tree of `ty`.
    fn js_ty(&mut self, resolve: &Resolve, ty: &Type) -> String {
        let ty = match ty {
            Type::Id(id) => {
                if let Some(r) = self.type_ref(resolve, *id, true) {
                    return r;
                }
                return self.js_kind(resolve, &resolve.types[*id].kind);
            }
            Type::Bool => "bool",
            Type::U8 => "u8",
            Type::U16 => "u16",
            Type::U32 => "u32",
            Type::U64 => "u64",
            Type::S8 => "s8",
            Type::S16 => "s16",
            Type::S32 => "s32",
            Type::S64 => "s64",
            Type::F32 => "f32",
            Type::F64 => "f64",
            Type::Char => "char",
            Type::String => "string",
            Type::ErrorContext => "tuple()",
        };
        self.m.runtime.insert("t");
        format!("$t.{ty}")
    }

    fn js_opt_ty(&mut self, resolve: &Resolve, ty: Option<&Type>) -> String {
        match ty {
            Some(ty) => self.js_ty(resolve, ty),
            None => "null".to_string(),
        }
    }

    fn js_kind(&mut self, resolve: &Resolve, kind: &TypeDefKind) -> String {
        if let TypeDefKind::Type(ty) = kind {
            return self.js_ty(resolve, ty);
        }
        self.m.runtime.insert("t");
        match kind {
            TypeDefKind::Record(r) => {
                let fields: Vec<_> = r
                    .fields
                    .iter()
                    .map(|f| format!("{:?}: {}", f.name, self.js_ty(resolve, &f.ty)))
                    .collect();
                format!("$t.record({{ {} }})", fields.join(", "))
            }
            TypeDefKind::Resource => panic!("resources have no type tree"),
            TypeDefKind::Handle(Handle::Own(id)) => {
                let name = resolve.types[dealias(resolve, *id)].name.as_deref();
                format!("$t.own({:?})", name.unwrap_or_default())
            }
            TypeDefKind::Handle(Handle::Borrow(id)) => {
                let name = resolve.types[dealias(resolve, *id)].name.as_deref();
                format!("$t.borrow({:?})", name.unwrap_or_default())
            }
            TypeDefKind::Flags(f) => {
                let names: Vec<_> = f.flags.iter().map(|f| format!("{:?}", f.name)).collect();
                format!("$t.flags([{}])", names.join(", "))
            }
            TypeDefKind::Tuple(t) => {
                let types: Vec<_> = t.types.iter().map(|ty| self.js_ty(resolve, ty)).collect();
                format!("$t.tuple({})", types.join(", "))
            }
            TypeDefKind::Variant(v) => {
                let cases: Vec<_> = v
                    .cases
                    .iter()
                    .map(|c| format!("{:?}: {}", c.name, self.js_opt_ty(resolve, c.ty.as_ref())))
                    .collect();
                format!("$t.variant({{ {} }})", cases.join(", "))
            }
            TypeDefKind::Enum(e) => {
                let names: Vec<_> = e.cases.iter().map(|c| format!("{:?}", c.name)).collect();
                format!("$t.enum([{}])", names.join(", "))
            }
            TypeDefKind::Option(ty) => format!("$t.option({})", self.js_ty(resolve, ty)),
            TypeDefKind::Result(r) => {
                let ok = self.js_opt_ty(resolve, r.ok.as_ref());
                let err = self.js_opt_ty(resolve, r.err.as_ref());
                format!("$t.result({ok}, {err})")
            }
            TypeDefKind::List(ty) => format!("$t.list({})", self.js_ty(resolve, ty)),
            TypeDefKind::Future(Some(ty)) => format!("$t.future({})", self.js_ty(resolve, ty)),
            TypeDefKind::Future(None) => "$t.future()".to_string(),
            TypeDefKind::Stream(Some(ty)) => format!("$t.stream({})", self.js_ty(resolve, ty)),
            TypeDefKind::Stream(None) => "$t.stream($t.tuple())".to_string(),
            TypeDefKind::Type(..) | TypeDefKind::Unknown => unreachable!(),
            TypeDefKind::Map(..) => panic!("unsupported type: map"),
            TypeDefKind::FixedLengthList(..) => panic!("unsupported type: fixed length list"),
        }
    }

    /// The TypeScript type of values of `ty`.
    fn ts_ty(&mut self, resolve: &Resolve, ty: &Type) -> String {
        match ty {
            Type::Id(id) => {
                if let Some(r) = self.type_ref(resolve, *id, false) {
                    return r;
                }
                self.ts_kind(resolve, &resolve.types[*id].kind)
            }
            Type::Bool => "boolean".to_string(),
            Type::U8
            | Type::U16
            | Type::U32
            | Type::S8
            | Type::S16
            | Type::S32
            | Type::F32
            | Type::F64 => "number".to_string(),
            Type::U64 | Type::S64 => "bigint".to_string(),
            Type::Char | Type::String => "string".to_string(),
            Type::ErrorContext => "[]".to_string(),
        }
    }

    fn ts_opt_ty(&mut self, resolve: &Resolve, ty: Option<&Type>) -> String {
        match ty {
            Some(ty) => self.ts_ty(resolve, ty),
            None => "void".to_string(),
        }
    }

    /// The TypeScript type of the `list` values or `stream` chunks of `ty`.
    fn ts_list(&mut self, resolve: &Resolve, ty: &Type) -> String {
        let array = match peel(resolve, *ty) {
            Type::U8 => "globalThis.Uint8Array",
            Type::S8 => "globalThis.Int8Array",
            Type::U16 => "globalThis.Uint16Array",
            Type::S16 => "globalThis.Int16Array",
            Type::U32 => "globalThis.Uint32Array",
            Type::S32 => "globalThis.Int32Array",
            Type::U64 => "globalThis.BigUint64Array",
            Type::S64 => "globalThis.BigInt64Array",
            Type::F32 => "globalThis.Float32Array",
            Type::F64 => "globalThis.Float64Array",
            _ => return format!("globalThis.Array<{}>", self.ts_ty(resolve, ty)),
        };
        array.to_string()
    }

    fn ts_tagged(&mut self, resolve: &Resolve, kind: &str, ty: Option<&Type>) -> String {
        match ty {
            Some(ty) => format!("{{ kind: {kind:?}; value: {} }}", self.ts_ty(resolve, ty)),
            None => format!("{{ kind: {kind:?} }}"),
        }
    }

    fn ts_kind(&mut self, resolve: &Resolve, kind: &TypeDefKind) -> String {
        match kind {
            TypeDefKind::Record(r) => {
                let fields: Vec<_> = r
                    .fields
                    .iter()
                    .map(|f| format!("{}: {}", camel_case(&f.name), self.ts_ty(resolve, &f.ty)))
                    .collect();
                format!("{{ {} }}", fields.join("; "))
            }
            TypeDefKind::Resource => "globalThis.Uint8Array".to_string(),
            TypeDefKind::Handle(Handle::Own(id) | Handle::Borrow(id)) => {
                self.ts_ty(resolve, &Type::Id(*id))
            }
            TypeDefKind::Flags(f) => {
                let flags: Vec<_> = f
                    .flags
                    .iter()
                    .map(|f| format!("{}: boolean", camel_case(&f.name)))
                    .collect();
                format!("{{ {} }}", flags.join("; "))
            }
            TypeDefKind::Tuple(t) => {
                let types: Vec<_> = t.types.iter().map(|ty| self.ts_ty(resolve, ty)).collect();
                format!("[{}]", types.join(", "))
            }
            TypeDefKind::Variant(v) => {
                let cases: Vec<_> = v
                    .cases
                    .iter()
                    .map(|c| self.ts_tagged(resolve, &c.name, c.ty.as_ref()))
                    .collect();
                cases.join(" | ")
            }
            TypeDefKind::Enum(e) => {
                let names: Vec<_> = e.cases.iter().map(|c| format!("{:?}", c.name)).collect();
                names.join(" | ")
            }
            TypeDefKind::Option(ty) => {
                if is_option(resolve, *ty) {
                    format!(
                        "{} | {{ kind: \"none\" }}",
                        self.ts_tagged(resolve, "some", Some(ty))
                    )
                } else {
                    format!("{} | undefined", self.ts_ty(resolve, ty))
                }
            }
            TypeDefKind::Result(r) => {
                let ok = self.ts_tagged(resolve, "ok", r.ok.as_ref());
                let err = self.ts_tagged(resolve, "error", r.err.as_ref());
                format!("{ok} | {err}")
            }
            TypeDefKind::List(ty) => self.ts_list(resolve, ty),
            TypeDefKind::Future(ty) => format!(
                "globalThis.Promise<{}>",
                self.ts_opt_ty(resolve, ty.as_ref())
            ),
            TypeDefKind::Stream(Some(ty)) => {
                format!("globalThis.AsyncIterable<{}>", self.ts_list(resolve, ty))
            }
            TypeDefKind::Stream(None) => {
                "globalThis.AsyncIterable<globalThis.Array<[]>>".to_string()
            }
            TypeDefKind::Type(ty) => self.ts_ty(resolve, ty),
            TypeDefKind::Map(..) => panic!("unsupported type: map"),
            TypeDefKind::FixedLengthList(..) => panic!("unsupported type: fixed length list"),
            TypeDefKind::Unknown => unreachable!(),
        }
    }

    /// The named types owned by `owner` that `ty` refers to.
    fn local_deps(resolve: &Resolve, owner: TypeOwner, ty: &Type, deps: &mut Vec<TypeId>) {
        let Type::Id(id) = ty else {
            return;
        };
        let def = &resolve.types[*id];
        if def.name.is_some() {
            if def.owner == owner {
                deps.push(*id);
            }
            return;
        }
        Self::local_kind_deps(resolve, owner, &def.kind, deps);
    }

    fn local_kind_deps(
        resolve: &Resolve,
        owner: TypeOwner,
        kind: &TypeDefKind,
        deps: &mut Vec<TypeId>,
    ) {
        match kind {
            TypeDefKind::Record(r) => {
                for f in &r.fields {
                    Self::local_deps(resolve, owner, &f.ty, deps);
                }
            }
            TypeDefKind::Tuple(t) => {
                for ty in &t.types {
                    Self::local_deps(resolve, owner, ty, deps);
                }
            }
            TypeDefKind::Variant(v) => {
                for ty in v.cases.iter().filter_map(|c| c.ty.as_ref()) {
                    Self::local_deps(resolve, owner, ty, deps);
                }
            }
            TypeDefKind::Result(r) => {
                for ty in r.ok.iter().chain(&r.err) {
                    Self::local_deps(resolve, owner, ty, deps);
                }
            }
            TypeDefKind::Option(ty)
            | TypeDefKind::List(ty)
            | TypeDefKind::Type(ty)
            | TypeDefKind::Future(Some(ty))
            | TypeDefKind::Stream(Some(ty)) => Self::local_deps(resolve, owner, ty, deps),
            _ => {}
        }
    }

    /// Define the named types `ids`, with the type trees in dependency order.
    fn define_types(&mut self, resolve: &Resolve, ids: &[TypeId]) {
        let mut done = HashSet::default();
        for id in ids {
            self.define_type(resolve, *id, &mut done);
        }
    }

    fn define_type(&mut self, resolve: &Resolve, id: TypeId, done: &mut HashSet<TypeId>) {
        if !done.insert(id) {
            return;
        }
        let def = &resolve.types[id];
        let mut deps = Vec::default();
        Self::local_kind_deps(resolve, def.owner, &def.kind, &mut deps);
        for dep in deps {
            self.define_type(resolve, dep, done);
        }

        let name = type_name(def.name.as_deref().expect("type name missing"));
        let ts = self.ts_kind(resolve, &def.kind);
        self.m.dts.push_str(&ts_docs(&def.docs, ""));
        uwriteln!(self.m.dts, "export type {name} = {ts};");
        if matches!(
            resolve.types[dealias(resolve, id)].kind,
            TypeDefKind::Resource
        ) {
            return;
        }
        self.m.wrpc_types = true;
        uwriteln!(self.m.dts, "export declare const {name}: $wrpc.Type;");
        let js = self.js_kind(resolve, &def.kind);
        uwriteln!(self.m.js, "export const {name} = {js};");
    }

    fn is_async(resolve: &Resolve, ty: &Type) -> bool {
        let (paths, fut) = async_paths_ty(resolve, ty);
        fut || !paths.is_empty()
    }

    /// Group `funcs` into those not bound to a resource and those of each
    /// resource.
    fn group<'b>(funcs: &[&'b Function]) -> (Vec<&'b Function>, Vec<(TypeId, Vec<&'b Function>)>) {
        let mut free = Vec::default();
        let mut resources: Vec<(TypeId, Vec<&Function>)> = Vec::default();
        for func in funcs {
            match func_resource(func) {
                None => free.push(*func),
                Some(id) => match resources.iter_mut().find(|(r, ..)| *r == id) {
                    Some((.., funcs)) => funcs.push(func),
                    None => resources.push((id, vec![func])),
                },
            }
        }
        (free, resources)
    }

    fn ts_params(&mut self, resolve: &Resolve, func: &Function) -> Vec<String> {
        func.params
            .iter()
            .map(|p| format!("{}: {}", param_ident(&p.name), self.ts_ty(resolve, &p.ty)))
            .collect()
    }

    /// Generate the client functions invoking `funcs` of `instance`.
    fn client_funcs(&mut self, resolve: &Resolve, instance: &str, funcs: &[&Function]) {
        let (free, resources) = Self::group(funcs);
        for func in free {
            let name = match func_name(func).as_str() {
                s @ ("serve" | "serveInterface") if self.path == self.world => format!("{s}_"),
                s => s.to_string(),
            };
            let (params, sig) = self.client_signature(resolve, func);
            let body = self.client_body(resolve, instance, func, "  ");
            self.m.dts.push_str(&ts_docs(&func.docs, ""));
            uwriteln!(self.m.dts, "export function {name}{sig};");
            uwriteln!(
                self.m.js,
                "export async function {name}({params}) {{\n{body}}}"
            );
        }
        for (id, funcs) in resources {
            let name = type_name(
                resolve.types[id]
                    .name
                    .as_deref()
                    .expect("resource name missing"),
            );
            uwriteln!(self.m.dts, "export declare const {name}: {{");
            uwriteln!(self.m.js, "export const {name} = {{");
            for func in funcs {
                let key = func_name(func);
                let (params, sig) = self.client_signature(resolve, func);
                let body = self.client_body(resolve, instance, func, "    ");
                self.m.dts.push_str(&ts_docs(&func.docs, "  "));
                uwriteln!(self.m.dts, "  {key:?}{sig};");
                uwriteln!(self.m.js, "  async {key}({params}) {{\n{body}  }},");
            }
            self.m.dts.push_str("};\n");
            self.m.js.push_str("};\n");
        }
    }

    /// The parameter list and the TypeScript signature of the client of
    /// `func`.
    fn client_signature(&mut self, resolve: &Resolve, func: &Function) -> (String, String) {
        let mut params = vec!["transport".to_string()];
        params.extend(func.params.iter().map(|p| param_ident(&p.name)));
        self.m.wrpc_types = true;
        let mut ts_params = vec!["transport: $wrpc.Transport".to_string()];
        ts_params.extend(self.ts_params(resolve, func));
        let result = self.ts_opt_ty(resolve, func.result.as_ref());
        let result = if Self::func_is_async(resolve, func) {
            match func.result {
                Some(..) => format!("{{ result: {result}; finished: globalThis.Promise<void> }}"),
                None => "{ finished: globalThis.Promise<void> }".to_string(),
            }
        } else {
            result
        };
        (
            params.join(", "),
            format!("({}): globalThis.Promise<{result}>", ts_params.join(", ")),
        )
    }

    fn func_is_async(resolve: &Resolve, func: &Function) -> bool {
        func.params.iter().any(|p| Self::is_async(resolve, &p.ty))
            || func.result.is_some_and(|ty| Self::is_async(resolve, &ty))
    }

    fn client_body(
        &mut self,
        resolve: &Resolve,
        instance: &str,
        func: &Function,
        indent: &str,
    ) -> String {
        self.m.runtime.insert("invoke");
        let types: Vec<_> = func
            .params
            .iter()
            .map(|p| self.js_ty(resolve, &p.ty))
            .collect();
        let args: Vec<_> = func.params.iter().map(|p| param_ident(&p.name)).collect();
        let results = match &func.result {
            Some(ty) => self.js_ty(resolve, ty),
            None => String::default(),
        };
        let mut out = format!(
            "{indent}const $r = await $invoke(transport, {instance:?}, {:?}, [{}], [{}], [{results}]);\n",
            rpc_func_name(func),
            types.join(", "),
            args.join(", "),
        );
        if Self::func_is_async(resolve, func) {
            if func.result.is_some() {
                uwriteln!(
                    out,
                    "{indent}return {{ result: $r.results[0], finished: $r.finished }};"
                );
            } else {
                uwriteln!(out, "{indent}return {{ finished: $r.finished }};");
            }
        } else {
            uwriteln!(out, "{indent}await $r.finished;");
            if func.result.is_some() {
                uwriteln!(out, "{indent}return $r.results[0];");
            }
        }
        out
    }

    /// Generate the `Handler` of `funcs` and `serveInterface`, serving their
    /// invocations. Returns whether there are any.
    fn serve_funcs(&mut self, resolve: &Resolve, funcs: &[&Function]) -> bool {
        if funcs.is_empty() {
            return false;
        }
        let (free, resources) = Self::group(funcs);
        let mut cases = String::default();
        self.m.dts.push_str("export interface Handler {\n");
        for func in free {
            let name = camel_case(&func.name);
            let sig = self.handler_signature(resolve, func);
            self.m.dts.push_str(&ts_docs(&func.docs, "  "));
            uwriteln!(self.m.dts, "  {name:?}{sig};");
            self.serve_case(resolve, func, &format!("handler.{name}"), &mut cases);
        }
        for (id, funcs) in resources {
            let name = type_name(
                resolve.types[id]
                    .name
                    .as_deref()
                    .expect("resource name missing"),
            );
            uwriteln!(self.m.dts, "  {name}: {{");
            for func in funcs {
                let key = func_name(func);
                let sig = self.handler_signature(resolve, func);
                self.m.dts.push_str(&ts_docs(&func.docs, "    "));
                uwriteln!(self.m.dts, "    {key:?}{sig};");
                self.serve_case(resolve, func, &format!("handler.{name}.{key}"), &mut cases);
            }
            self.m.dts.push_str("  };\n");
        }
        self.m.dts.push_str("}\n");
        self.m.wrpc_types = true;
        self.m.dts.push_str(
            "export function serveInterface(inv: $wrpc.Invocation, handler: Handler): globalThis.Promise<void>;\n",
        );
        self.m
            .js
            .push_str("export async function serveInterface(inv, handler) {\n");
        self.m.js.push_str("  switch (inv.func) {\n");
        self.m.js.push_str(&cases);
        self.m.js.push_str(
            r"    default:
      throw new globalThis.Error(`unknown function \`${inv.func}\` of instance \`${inv.instance}\``);
  }
}
",
        );
        true
    }

    fn handler_signature(&mut self, resolve: &Resolve, func: &Function) -> String {
        let params = self.ts_params(resolve, func);
        let result = self.ts_opt_ty(resolve, func.result.as_ref());
        if func.result.is_some_and(|ty| may_be_promise(resolve, ty)) {
            format!("({}): {result}", params.join(", "))
        } else {
            format!(
                "({}): {result} | globalThis.Promise<{result}>",
                params.join(", ")
            )
        }
    }

    fn serve_case(&mut self, resolve: &Resolve, func: &Function, handler: &str, out: &mut String) {
        let params: Vec<_> = func
            .params
            .iter()
            .map(|p| self.js_ty(resolve, &p.ty))
            .collect();
        uwriteln!(out, "    case {:?}: {{", rpc_func_name(func));
        uwriteln!(
            out,
            "      const {{ params }} = await inv.receiveParams([{}]);",
            params.join(", ")
        );
        match func.result {
            Some(ty) => {
                let call = if may_be_promise(resolve, ty) {
                    ""
                } else {
                    "await "
                };
                let ty = self.js_ty(resolve, &ty);
                uwriteln!(
                    out,
                    "      await inv.sendResults([{ty}], [{call}{handler}(...params)]);"
                );
            }
            None => {
                uwriteln!(out, "      await {handler}(...params);");
                uwriteln!(out, "      await inv.sendResults([], []);");
            }
        }
        uwriteln!(out, "      return;");
        uwriteln!(out, "    }}");
    }
}

impl WorldGenerator for JsWrpc {
    fn preprocess(&mut self, resolve: &Resolve, world: WorldId) -> Result<()> {
        let world = &resolve.worlds[world];
        self.world.clone_from(&world.name);
        for (key, item) in world.imports.iter().chain(world.exports.iter()) {
            if let WorldItem::Interface { id, .. } = item
                && resolve.interfaces[*id].package == world.package
            {
                self.with
                    .insert(resolve.name_world_key(key), WithOption::Generate);
            }
        }
        for (k, v) in &self.opts.with {
            self.with.insert(k.clone(), v.clone());
        }
        Ok(())
    }

    fn import_interface(
        &mut self,
        resolve: &Resolve,
        name: &WorldKey,
        id: InterfaceId,
        _files: &mut Files,
    ) -> Result<()> {
        let Some(path) = self.name_interface(resolve, id, name, false)? else {
            return Ok(());
        };
        let iface = &resolve.interfaces[id];
        let mut r#gen = self.module(path.clone(), Module::default());
        let types: Vec<_> = iface.types.values().copied().collect();
        r#gen.define_types(resolve, &types);
        let funcs: Vec<_> = iface.functions.values().collect();
        r#gen.client_funcs(resolve, &interface_instance(resolve, name, id), &funcs);
        let m = r#gen.m;
        self.modules.push((path, m));
        Ok(())
    }

    fn import_types(
        &mut self,
        resolve: &Resolve,
        _world: WorldId,
        types: &[(&str, TypeId)],
        _files: &mut Files,
    ) {
        let m = mem::take(&mut self.world_module);
        let mut r#gen = self.module(self.world.clone(), m);
        let types: Vec<_> = types.iter().map(|(.., id)| *id).collect();
        r#gen.define_types(resolve, &types);
        self.world_module = r#gen.m;
    }

    fn import_funcs(
        &mut self,
        resolve: &Resolve,
        _world: WorldId,
        funcs: &[(&str, &Function)],
        _files: &mut Files,
    ) {
        let m = mem::take(&mut self.world_module);
        let mut r#gen = self.module(self.world.clone(), m);
        let funcs: Vec<_> = funcs.iter().map(|(.., f)| *f).collect();
        r#gen.client_funcs(resolve, "", &funcs);
        self.world_module = r#gen.m;
    }

    fn export_interface(
        &mut self,
        resolve: &Resolve,
        name: &WorldKey,
        id: InterfaceId,
        _files: &mut Files,
    ) -> Result<()> {
        let instance = interface_instance(resolve, name, id);
        let Some(path) = self.name_interface(resolve, id, name, true)? else {
            unreachable!("exports are always generated")
        };
        let iface = &resolve.interfaces[id];
        let mut r#gen = self.module(path.clone(), Module::default());
        let types: Vec<_> = iface.types.values().copied().collect();
        r#gen.define_types(resolve, &types);
        let funcs: Vec<_> = iface.functions.values().collect();
        let exports = r#gen.serve_funcs(resolve, &funcs);
        let m = r#gen.m;
        self.modules.push((path.clone(), m));
        if exports {
            self.exports.push((instance, Some(ModulePath::Local(path))));
        }
        Ok(())
    }

    fn export_funcs(
        &mut self,
        resolve: &Resolve,
        _world: WorldId,
        funcs: &[(&str, &Function)],
        _files: &mut Files,
    ) -> Result<()> {
        let m = mem::take(&mut self.world_module);
        let mut r#gen = self.module(self.world.clone(), m);
        let funcs: Vec<_> = funcs.iter().map(|(.., f)| *f).collect();
        let exports = r#gen.serve_funcs(resolve, &funcs);
        self.world_module = r#gen.m;
        if exports {
            self.exports.push((String::default(), None));
        }
        Ok(())
    }

    fn finish(&mut self, _resolve: &Resolve, _world: WorldId, files: &mut Files) -> Result<()> {
        let mut unused: Vec<_> = self
            .opts
            .with
            .iter()
            .map(|(k, ..)| k)
            .filter(|k| !self.used_with.contains(*k))
            .collect();
        unused.sort();
        if !unused.is_empty() {
            bail!("unused remappings provided via `with`: {unused:?}");
        }
        let m = mem::take(&mut self.world_module);
        let mut r#gen = self.module(self.world.clone(), m);
        if !self.exports.is_empty() {
            r#gen.m.runtime.insert("accept");
            let mut params = vec!["transport".to_string()];
            r#gen.m.wrpc_types = true;
            let mut ts_params = vec!["transport: $wrpc.Transport".to_string()];
            let mut cases = String::default();
            for (i, (instance, path)) in self.exports.iter().enumerate() {
                params.push(format!("h{i}"));
                let (handler, serve) = match path {
                    Some(path) => {
                        let dep = r#gen.dep(path, true);
                        (format!("{dep}.Handler"), format!("{dep}.serveInterface"))
                    }
                    None => ("Handler".to_string(), "serveInterface".to_string()),
                };
                ts_params.push(format!("h{i}: {handler}"));
                uwrite!(
                    cases,
                    "      case {instance:?}:\n        await {serve}(inv, h{i});\n        break;\n"
                );
            }
            uwriteln!(
                r#gen.m.dts,
                "export function serve({}): globalThis.Promise<void>;",
                ts_params.join(", ")
            );
            uwrite!(
                r#gen.m.js,
                "export async function serve({}) {{
  const inv = await $accept(transport);
  try {{
    switch (inv.instance) {{
{cases}      default:
        throw new globalThis.Error(`unknown instance \\`${{inv.instance}}\\``);
    }}
    await inv.finished;
  }} catch (err) {{
    inv.mux.abort(err);
    throw err;
  }}
}}
",
                params.join(", ")
            );
        }
        let world = (r#gen.path, r#gen.m);
        let wrpc = self
            .opts
            .wrpc_path
            .as_deref()
            .unwrap_or("@bytecodealliance/wrpc");
        for (path, m) in mem::take(&mut self.modules).into_iter().chain([world]) {
            let (js, dts) = m.render(wrpc);
            files.push(&format!("{path}.js"), js.as_bytes());
            files.push(&format!("{path}.d.ts"), dts.as_bytes());
        }
        Ok(())
    }
}
